12	const ChangePasswordCard = () => {
13	  const [newPassword, setNewPassword] = useState("");
14	  const [confirmPassword, setConfirmPassword] = useState("");
15	  const [saving, setSaving] = useState(false);
16	  const [showPassword, setShowPassword] = useState(false);
17	
18	  const handleChangePassword = async () => {
19	    if (newPassword.length < 6) {
20	      toast.error("Password too short — must be at least 6 characters.");
21	      return;
22	    }
23	    if (newPassword !== confirmPassword) {
24	      toast.error("Passwords don't match");
25	      return;
26	    }
27	    setSaving(true);
28	    const { error } = await supabase.auth.updateUser({ password: newPassword });
29	    if (error) {
30	      toast.error(error.message);
31	    } else {
32	      toast.success("Password updated");
33	      setNewPassword("");
34	      setConfirmPassword("");
35	    }
36	    setSaving(false);
37	  };
38	
39	  const passwordsMatch = newPassword && confirmPassword && newPassword === confirmPassword;
40	  const passwordsMismatch = confirmPassword && newPassword !== confirmPassword;
41	
42	  return (
43	    <Card className="overflow-hidden">
44	      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
45	        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
46	          <Shield className="h-4.5 w-4.5 text-primary" />
47	        </div>
48	        <div>
49	          <h3 className="text-sm font-semibold text-foreground">Change Password</h3>
50	          <p className="text-xs text-muted-foreground">Update your account password.</p>
