56	          <p className="text-xs text-muted-foreground">At least 6 characters required</p>
57	          <div className="relative">
58	            <Input
59	              id="new-password"
60	              type={showPassword ? "text" : "password"}
61	              placeholder="Min 6 characters"
62	              value={newPassword}
63	              onChange={(e) => setNewPassword(e.target.value)}
64	              className="pr-10"
65	            />
66	            <button
67	              type="button"
68	              onClick={() => setShowPassword(!showPassword)}
69	              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
70	              aria-label={showPassword ? "Hide password" : "Show password"}
