 // @ts-nocheck
// deno-lint-ignore-file no-explicit-any
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
import { corsHeaders, handlePreflight } from "../_shared/cors.ts";

Deno.serve(async (req) => {
  const cors = corsHeaders(req);

  const preflight = handlePreflight(req);
  if (preflight) return preflight;

  try {
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");

    if (!DODO_API_KEY) {
      return new Response(JSON.stringify({ error: "Dodo Payments not configured" }), {
        status: 500, headers: { ...cors, "Content-Type": "application/json" },
      });
    }

    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401, headers: { ...cors, "Content-Type": "application/json" },
      });
    }

    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      global: { headers: { Authorization: authHeader } },
    });
    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    if (userError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401, headers: { ...cors, "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // Get user's dodo subscription ID
    const { data: profile } = await supabase
      .from("profiles")
      .select("dodo_subscription_id")
      .eq("user_id", user.id)
      .single();

    if (!profile?.dodo_subscription_id) {
      return new Response(JSON.stringify({ error: "No active Dodo subscription found" }), {
        status: 400, headers: { ...cors, "Content-Type": "application/json" },
      });
    }

    // Cancel at period end via Dodo SDK (recommended)
    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
    const isLive = DODO_ENV === "live_mode";
    const dodo = new DodoPayments({
      bearerToken: DODO_API_KEY!,
      baseURL: isLive
        ? "https://live.dodopayments.com"
        : "https://test.dodopayments.com",
    });

    await dodo.subscriptions.update(profile.dodo_subscription_id, {
      cancel_at_next_billing_date: true,
    });

    // Update profile — subscription will remain active until end of period
    // The webhook will handle the final downgrade

    return new Response(JSON.stringify({ success: true, message: "Subscription will cancel at end of billing period" }), {
      headers: { ...cors, "Content-Type": "application/json" },
    });
  } catch (err: unknown) {
    console.error("cancel-dodo-subscription error:", err);
    await logSystemError({
      function_name: "cancel-dodo-subscription",
      error_type: "SUBSCRIPTION_CANCEL_ERROR",
      severity: "critical",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
      status: 500, headers: { ...cors, "Content-Type": "application/json" },
    });
  }
});

