import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

function getAllowedOrigin(req: Request): string {
  const origin = req.headers.get("origin") || "";
  const allowed = ["https://rankora.co", "https://www.rankora.co", "http://localhost:8080", "http://localhost:5173"];
  return allowed.includes(origin) ? origin : "https://rankora.co";
}

const baseCorsHeaders = {
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface SendEmailRequest {
  to: string;
  template_key: string;
  variables: Record<string, string>;
}

/** Replace {{variable}} placeholders in a template string */
function renderTemplate(template: string, variables: Record<string, string>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => variables[key] ?? "");
}

/** Send an email via Resend API */
async function sendViaResend(
  apiKey: string,
  from: { email: string; name: string },
  to: string,
  subject: string,
  htmlContent: string
): Promise<{ ok: boolean; status: number; body: string; errorMessage?: string }> {
  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: `${from.name} <${from.email}>`,
      to: [to],
      subject,
      html: htmlContent,
    }),
  });

  const body = await res.text();
  let errorMessage: string | undefined;

  if (!res.ok) {
    try {
      const parsed = JSON.parse(body);
      errorMessage = parsed.message || parsed.error?.message;
    } catch { /* ignore */ }
  }

  return { ok: res.ok, status: res.status, body, errorMessage };
}

