"use client";

import { useMemo } from "react";
import { useQuery, useQueryClient, useMutation } from "@tanstack/react-query";
import { Mail, Bell as BellIcon } from "lucide-react";
import { toast } from "sonner";

import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Skeleton } from "@/components/ui/skeleton";
import {
  NOTIFICATION_EVENTS,
  type NotificationEventKey,
} from "@/components/settings/notification-events";

type PrefRow = {
  user_id: string;
  event_key: NotificationEventKey;
  email_enabled: boolean;
  in_app_enabled: boolean;
};

type Channel = "email_enabled" | "in_app_enabled";

const QUERY_KEY = ["notification-preferences"] as const;

const NotificationsTab = () => {
  const { user } = useAuth();
  const qc = useQueryClient();

  const { data: prefs, isLoading } = useQuery({
    queryKey: [...QUERY_KEY, user?.id],
    enabled: !!user,
    queryFn: async () => {
      if (!user) return [] as PrefRow[];
      const { data, error } = await supabase
        .from("notification_preferences")
        .select("user_id, event_key, email_enabled, in_app_enabled")
        .eq("user_id", user.id);
      if (error) throw error;
      return (data ?? []) as PrefRow[];
    },
    staleTime: 30_000,
  });

  const prefsByEvent = useMemo(() => {
    const map = new Map<NotificationEventKey, PrefRow>();
    (prefs ?? []).forEach((row) => map.set(row.event_key, row));
    return map;
  }, [prefs]);

  const upsert = useMutation({
    mutationFn: async ({
      eventKey,
      channel,
      value,
    }: {
      eventKey: NotificationEventKey;
      channel: Channel;
      value: boolean;
    }) => {
      if (!user) throw new Error("Not signed in");
      const existing = prefsByEvent.get(eventKey);
      const row = {
        user_id: user.id,
        event_key: eventKey,
        email_enabled:
          channel === "email_enabled"
            ? value
            : (existing?.email_enabled ?? true),
        in_app_enabled:
          channel === "in_app_enabled"
            ? value
            : (existing?.in_app_enabled ?? true),
      };
      const { error } = await supabase
        .from("notification_preferences")
        .upsert(row, { onConflict: "user_id,event_key" });
      if (error) throw error;
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: QUERY_KEY });
    },
    onError: (err: unknown) => {
      const msg = err instanceof Error ? err.message : "Failed to save";
      toast.error(msg);
    },
  });

  return (
    <div className="px-6 sm:px-8 lg:px-10 py-8 space-y-6">
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-sm font-semibold">
            Email &amp; in-app notifications
          </CardTitle>
          <CardDescription>
            Choose how we reach you for each event. Changes save instantly.
          </CardDescription>
        </CardHeader>
        <CardContent className="px-6 pb-5">
          <div className="hidden sm:grid grid-cols-[minmax(0,1fr)_auto_auto] items-center gap-x-8 pb-2 border-b border-border/40 mb-2">
            <div />
            <ChannelHeader icon={<Mail className="h-3.5 w-3.5" />} label="Email" />
            <ChannelHeader icon={<BellIcon className="h-3.5 w-3.5" />} label="In-app" />
          </div>

          {isLoading ? (
            <div className="space-y-3 py-2">
              <Skeleton className="h-10 w-full" />
              <Skeleton className="h-10 w-full" />
              <Skeleton className="h-10 w-full" />
            </div>
          ) : (
            <ul className="divide-y divide-border/40">
              {NOTIFICATION_EVENTS.map((event) => {
                const row = prefsByEvent.get(event.key);
                const emailOn = row?.email_enabled ?? true;
                const inAppOn = row?.in_app_enabled ?? true;
                return (
                  <li
                    key={event.key}
                    className="grid grid-cols-1 sm:grid-cols-[minmax(0,1fr)_auto_auto] items-start sm:items-center gap-x-8 gap-y-2 py-3"
                  >
                    <div className="min-w-0">
                      <p className="text-sm font-medium text-foreground">
                        {event.title}
                      </p>
                      <p className="text-xs text-muted-foreground mt-0.5">
                        {event.description}
                      </p>
                    </div>

                    <div className="flex items-center gap-2 sm:justify-center">
                      <span className="text-xs text-muted-foreground sm:hidden">
                        Email
                      </span>
                      <Switch
                        checked={emailOn}
                        disabled={upsert.isPending}
                        onCheckedChange={(val) =>
                          upsert.mutate({
                            eventKey: event.key,
                            channel: "email_enabled",
                            value: val,
                          })
                        }
                        aria-label={`${event.title} — email`}
                      />
                    </div>

                    <div className="flex items-center gap-2 sm:justify-center">
                      <span className="text-xs text-muted-foreground sm:hidden">
                        In-app
                      </span>
                      <Switch
                        checked={inAppOn}
                        disabled={upsert.isPending}
                        onCheckedChange={(val) =>
                          upsert.mutate({
                            eventKey: event.key,
                            channel: "in_app_enabled",
                            value: val,
                          })
                        }
                        aria-label={`${event.title} — in-app`}
                      />
                    </div>
                  </li>
                );
              })}
            </ul>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

const ChannelHeader = ({
  icon,
  label,
}: {
  icon: React.ReactNode;
  label: string;
}) => (
  <div className="flex items-center justify-center gap-1.5 text-[11px] font-semibold uppercase tracking-[0.1em] text-muted-foreground/70">
    {icon}
    <span>{label}</span>
  </div>
);

export default NotificationsTab;

