"use client";

import { useState, useEffect, createContext, useContext, useRef } from "react";
import { supabase } from "@/integrations/supabase/browser";
import type { User, Session } from "@supabase/supabase-js";

type Profile = {
  credits: number;
  subscription_credits: number;
  topup_credits: number;
  bonus_credits: number;
  inbox_email: string | null;
  plan: string;
  email_enabled: boolean;
  auto_rank_enabled: boolean;
  subscription_ends_at: string | null;
};

interface AuthContextType {
  user: User | null;
  session: Session | null;
  loading: boolean;
  isAdmin: boolean;
  profile: Profile | null;
  /**
   * Non-null when either the profile or role fetch failed. Consumers
   * can surface a toast/banner; the rest of the app still renders.
   */
  authError: string | null;
  signOut: () => Promise<void>;
  refreshProfile: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  session: null,
  loading: true,
  isAdmin: false,
  profile: null,
  authError: null,
  signOut: async () => {},
  refreshProfile: async () => {},
});

// eslint-disable-next-line react-refresh/only-export-components
export const useAuth = () => useContext(AuthContext);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const userIdRef = useRef<string | null>(null);

  const fetchProfile = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from("profiles")
        .select(
          "credits, subscription_credits, topup_credits, bonus_credits, inbox_email, plan, email_enabled, auto_rank_enabled, subscription_ends_at",
        )
        .eq("user_id", userId)
        .single();
      if (error) throw error;
      if (data) {
        setProfile(data as Profile);
        setAuthError(null);
      }
    } catch (err) {
      console.error("[useAuth] Error fetching profile:", err);
      setAuthError(
        err instanceof Error
          ? `Could not load profile: ${err.message}`
          : "Could not load profile",
      );
    }
  };

