      return;
    }

    setUploading(true);
    try {
      const ext = file.name.split(".").pop() ?? "png";
      const path = `${user.id}/avatar.${ext}`;
      const { error: upErr } = await supabase.storage
        .from("avatars")
        .upload(path, file, { upsert: true, contentType: file.type });
      if (upErr) throw upErr;
      const { data: u } = supabase.storage.from("avatars").getPublicUrl(path);
      const url = `${u.publicUrl}?t=${Date.now()}`;
      const { error: dbErr } = await supabase
        .from("profiles")
        .update({ avatar_url: url } as never)
        .eq("user_id", user.id);
      if (dbErr) throw dbErr;
      setAvatarUrl(url);
      invalidate();
      toast.success("Photo updated");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Upload failed");
    } finally {
      setUploading(false);
      if (fileRef.current) fileRef.current.value = "";
    }
  };

  const removeAvatar = async () => {
    if (!user) return;
    setUploading(true);
    try {
      await supabase.storage
        .from("avatars")
        .remove([
          `${user.id}/avatar.jpg`,
          `${user.id}/avatar.jpeg`,
          `${user.id}/avatar.png`,
          `${user.id}/avatar.webp`,
        ]);
      const { error } = await supabase
        .from("profiles")
        .update({ avatar_url: null } as never)
        .eq("user_id", user.id);
      if (error) throw error;
      setAvatarUrl(null);
      invalidate();
      toast.success("Photo removed");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Could not remove photo");
    } finally {
      setUploading(false);
    }
  };

  const saveName = async () => {
    if (!user) return;
    setSaving(true);
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ full_name: fullName.trim() || null } as never)
        .eq("user_id", user.id);
      if (error) throw error;
      invalidate();
      toast.success("Name updated");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const initials =
    (fullName || user?.email || "?")
      .split(/\s+|@/)[0]
      .slice(0, 2)
      .toUpperCase() || "?";

  return (
    <Card className="overflow-hidden">
      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
          <UserCircle className="h-4.5 w-4.5 text-primary" />
        </div>
        <div>
          <h3 className="text-sm font-semibold text-foreground">Profile</h3>
          <p className="text-xs text-muted-foreground">
            Your name and avatar shown across the app.
          </p>
        </div>
      </div>
      <CardContent className="px-6 pt-3 pb-5 space-y-5">
        <div className="flex items-center gap-4">
          <Avatar className="h-16 w-16">
            {avatarUrl ? <AvatarImage src={avatarUrl} alt={fullName} /> : null}
            <AvatarFallback>{initials}</AvatarFallback>
          </Avatar>

          <div className="flex flex-wrap gap-2">
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={() => fileRef.current?.click()}
              disabled={uploading || !user}
            >
              <Camera className="h-4 w-4 mr-2" />
              {uploading ? "Uploading…" : avatarUrl ? "Change photo" : "Upload photo"}
            </Button>
            {avatarUrl ? (
              <Button
                type="button"
                size="sm"
                variant="ghost"
                onClick={removeAvatar}
                disabled={uploading}
              >
                <Trash2 className="h-4 w-4 mr-2" />
                Remove
              </Button>
            ) : null}
            <input
              ref={fileRef}
              type="file"
              accept="image/*"
              className="hidden"
              onChange={handleAvatar}
            />
          </div>
        </div>

        <div className="space-y-2">
          <Label htmlFor="profile-full-name" className="text-sm">
            Full name
          </Label>
          <div className="flex gap-2">
            <Input
              id="profile-full-name"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              placeholder="Your name"
              disabled={isLoading}
            />
            <Button
              onClick={saveName}
              disabled={saving || isLoading || fullName === (data?.full_name ?? "")}
              className="shrink-0"
            >
              {saving ? "Saving…" : "Save"}
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

export default ProfileCard;

