"use client";

import { useEffect, useState } from "react";
import { useTheme } from "next-themes";
import { Sun, Moon, Monitor, Palette } from "lucide-react";

import { Card, CardContent } from "@/components/ui/card";
import {
  ToggleGroup,
  ToggleGroupItem,
} from "@/components/ui/toggle-group";

type ThemeChoice = "light" | "dark" | "system";

const OPTIONS: { value: ThemeChoice; label: string; icon: React.ReactNode }[] = [
  { value: "light", label: "Light", icon: <Sun className="h-4 w-4" /> },
  { value: "dark", label: "Dark", icon: <Moon className="h-4 w-4" /> },
  { value: "system", label: "System", icon: <Monitor className="h-4 w-4" /> },
];

const ThemeCard = () => {
  const { theme, setTheme } = useTheme();
  const [mounted, setMounted] = useState(false);

  // next-themes needs the client to hydrate before `theme` is accurate.
  useEffect(() => setMounted(true), []);

  const current: ThemeChoice =
    mounted && (theme === "light" || theme === "dark" || theme === "system")
      ? (theme as ThemeChoice)
      : "system";

  return (
    <Card className="overflow-hidden">
      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
          <Palette className="h-4.5 w-4.5 text-primary" />
        </div>
        <div>
          <h3 className="text-sm font-semibold text-foreground">Appearance</h3>
          <p className="text-xs text-muted-foreground">
            Choose light, dark, or follow your device.
          </p>
        </div>
      </div>
      <CardContent className="px-6 pt-3 pb-5">
        <ToggleGroup
          type="single"
          value={current}
          onValueChange={(val) => {
            if (val === "light" || val === "dark" || val === "system") {
              setTheme(val);
            }
          }}
          className="inline-flex rounded-lg border border-border/60 p-1 bg-muted/40"
        >
          {OPTIONS.map((opt) => (
            <ToggleGroupItem
              key={opt.value}
              value={opt.value}
              aria-label={opt.label}
              className="data-[state=on]:bg-background data-[state=on]:shadow-sm rounded-md px-3 h-8 text-xs gap-1.5"
            >
              {opt.icon}
              {opt.label}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
      </CardContent>
    </Card>
  );
};

export default ThemeCard;

