"use client";

import { useEffect, useMemo, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { Clock } from "lucide-react";

import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

function listTimezones(): string[] {
  const IntlAny = Intl as unknown as {
    supportedValuesOf?: (input: string) => string[];
  };
  if (typeof IntlAny.supportedValuesOf === "function") {
    try {
      return IntlAny.supportedValuesOf("timeZone");
    } catch {
      // fall through
    }
  }
  // Small fallback list — any browser that actually ships to Rankora
  // supports Intl.supportedValuesOf, but be safe.
  return [
    "UTC",
    "America/New_York",
    "America/Chicago",
    "America/Denver",
    "America/Los_Angeles",
    "Europe/London",
    "Europe/Paris",
    "Europe/Berlin",
    "Asia/Kolkata",
    "Asia/Singapore",
    "Asia/Tokyo",
    "Australia/Sydney",
  ];
}

function browserTimezone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  } catch {
    return "UTC";
  }
}

const TimezoneCard = () => {
  const { user } = useAuth();
  const qc = useQueryClient();
  const zones = useMemo(listTimezones, []);
  const [value, setValue] = useState<string>(browserTimezone());
  const [saving, setSaving] = useState(false);

  const { data } = useQuery({
    queryKey: ["profile-timezone", user?.id],
    enabled: !!user,
    queryFn: async (): Promise<string | null> => {
      if (!user) return null;
      const { data, error } = await supabase
        .from("profiles")
        .select("timezone")
        .eq("user_id", user.id)
        .single();
      if (error) throw error;
      return (data as { timezone: string | null } | null)?.timezone ?? null;
    },
    staleTime: 60_000,
  });

  useEffect(() => {
    if (data) setValue(data);
  }, [data]);

  const save = async () => {
    if (!user) return;
    setSaving(true);
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ timezone: value } as never)
        .eq("user_id", user.id);
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["profile-timezone", user.id] });
      toast.success("Timezone saved");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const dirty = value !== (data ?? browserTimezone());

  return (
    <Card className="overflow-hidden">
      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
          <Clock className="h-4.5 w-4.5 text-primary" />
        </div>
        <div>
          <h3 className="text-sm font-semibold text-foreground">Timezone</h3>
          <p className="text-xs text-muted-foreground">
            Used to schedule availability and time-stamp activity.
          </p>
        </div>
      </div>
      <CardContent className="px-6 pt-3 pb-5">
        <div className="flex flex-col sm:flex-row gap-2">
          <Select value={value} onValueChange={setValue}>
            <SelectTrigger className="sm:flex-1">
              <SelectValue placeholder="Select a timezone" />
            </SelectTrigger>
            <SelectContent className="max-h-72">
              {zones.map((z) => (
                <SelectItem key={z} value={z}>
                  {z}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button onClick={save} disabled={saving || !dirty} className="shrink-0">
            {saving ? "Saving…" : "Save"}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
};

export default TimezoneCard;

