"use client";

import { useState } from "react";
import { toast } from "sonner";
import { AlertTriangle, Download, Trash2 } from "lucide-react";

import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

const DangerZoneCard = () => {
  const { user, signOut } = useAuth();
  const [requesting, setRequesting] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [confirmEmail, setConfirmEmail] = useState("");

  const exportData = async () => {
    if (!user) return;
    setRequesting(true);
    try {
      const { data, error } = await supabase.functions.invoke(
        "export-user-data",
        { body: {} },
      );
      if (error) throw error;
      const message =
        (data as { message?: string } | null)?.message ??
        "We'll email your export within 24h.";
      toast.success(message);
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Could not request export",
      );
    } finally {
      setRequesting(false);
    }
  };

  const deleteAccount = async () => {
    if (!user) return;
    setDeleting(true);
    try {
      const { error } = await supabase.functions.invoke(
        "delete-user-account",
        { body: {} },
      );
      if (error) throw error;
      toast.success("Account scheduled for deletion. Signing out…");
      setConfirmOpen(false);
      await signOut();
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Could not delete account",
      );
      setDeleting(false);
    }
  };

  const canConfirm =
    !!user?.email &&
    confirmEmail.trim().toLowerCase() === user.email.toLowerCase();

  return (
    <>
      <Card className="overflow-hidden border-destructive/40">
        <div className="flex items-center gap-3 px-6 pt-5 pb-2">
          <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-destructive/10">
            <AlertTriangle className="h-4.5 w-4.5 text-destructive" />
          </div>
          <div>
            <h3 className="text-sm font-semibold text-foreground">
              Danger zone
            </h3>
            <p className="text-xs text-muted-foreground">
              Export your data or permanently delete your account.
            </p>
          </div>
        </div>
        <CardContent className="px-6 pt-3 pb-5 space-y-4">
          <div className="flex items-start justify-between gap-4 rounded-lg border border-border/60 bg-muted/20 p-3">
            <div className="min-w-0">
              <p className="text-sm font-medium">Export my data</p>
              <p className="text-xs text-muted-foreground mt-0.5">
                We'll email you a download link with your jobs, resumes, and
                rankings.
              </p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={exportData}
              disabled={requesting || !user}
            >
              <Download className="h-4 w-4 mr-2" />
              {requesting ? "Requesting…" : "Request export"}
            </Button>
          </div>

          <div className="flex items-start justify-between gap-4 rounded-lg border border-destructive/40 bg-destructive/5 p-3">
            <div className="min-w-0">
              <p className="text-sm font-medium text-destructive">
                Delete my account
              </p>
              <p className="text-xs text-muted-foreground mt-0.5">
                Cancels your subscription and marks your account for deletion.
                You have 30 days to reach out if this was a mistake.
              </p>
            </div>
            <Button
              variant="destructive"
              size="sm"
              onClick={() => setConfirmOpen(true)}
              disabled={deleting || !user}
            >
              <Trash2 className="h-4 w-4 mr-2" />
              Delete account
            </Button>
          </div>
        </CardContent>
      </Card>

      <AlertDialog open={confirmOpen} onOpenChange={setConfirmOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete your account?</AlertDialogTitle>
            <AlertDialogDescription>
              This cancels your subscription, hides your data, and signs you
              out. Type your email to confirm.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="space-y-2 py-2">
            <Label htmlFor="delete-confirm-email" className="text-sm">
              {user?.email}
            </Label>
            <Input
              id="delete-confirm-email"
              value={confirmEmail}
              onChange={(e) => setConfirmEmail(e.target.value)}
              placeholder="your@email.com"
              autoComplete="off"
            />
          </div>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              disabled={!canConfirm || deleting}
              onClick={(e) => {
                e.preventDefault();
                if (canConfirm) deleteAccount();
              }}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {deleting ? "Deleting…" : "Delete account"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

export default DangerZoneCard;

