/**
 * Shared CORS configuration for all edge functions.
 *
 * Origins are resolved at boot from environment variables:
 *   APP_URL              — primary app URL (e.g. https://rankora-develop.up.railway.app)
 *   EXTRA_ALLOWED_ORIGINS — comma-separated additional origins (optional)
 *
 * Default origins (always included): rankora.co, www.rankora.co,
 * localhost:8080, localhost:5173.
 *
 * To add a new origin without redeploying functions:
 *   supabase secrets set EXTRA_ALLOWED_ORIGINS="https://new-domain.com,https://other.com"
 *   supabase functions deploy <function-name>
 */

const DEFAULT_ORIGINS = [
  "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
];

function buildAllowedOrigins(): Set<string> {
  const origins = new Set(DEFAULT_ORIGINS);

  // Primary app URL — always first priority
  const appUrl = Deno.env.get("APP_URL");
  if (appUrl) origins.add(appUrl.replace(/\/$/, ""));

  // Extra origins — comma-separated, for staging/preview/custom domains
  const extra = Deno.env.get("EXTRA_ALLOWED_ORIGINS");
  if (extra) {
    for (const raw of extra.split(",")) {
      const trimmed = raw.trim().replace(/\/$/, "");
      if (trimmed) origins.add(trimmed);
    }
  }

  return origins;
}

const ALLOWED_ORIGINS = buildAllowedOrigins();
const FALLBACK_ORIGIN = Deno.env.get("APP_URL") || "https://rankora.co";

/**
 * Returns the origin to use in Access-Control-Allow-Origin.
 * If the request origin is in our allow-list, reflect it back.
 * Otherwise, return the primary APP_URL.
 */
export function getCorsOrigin(req: Request): string {
  const origin = req.headers.get("origin") || "";
  return ALLOWED_ORIGINS.has(origin) ? origin : FALLBACK_ORIGIN;
}

/** Standard CORS headers for most edge functions. */
export function corsHeaders(req: Request): Record<string, string> {
  return {
    "Access-Control-Allow-Origin": getCorsOrigin(req),
    "Access-Control-Allow-Headers":
      "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  };
}

/** Handle preflight OPTIONS request. */
export function handlePreflight(req: Request): Response | null {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders(req) });
  }
  return null;
}

