// @ts-nocheck
// deno-lint-ignore-file no-explicit-any
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { corsHeaders, handlePreflight } from "../_shared/cors.ts";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

/**
 * Request an export of the caller's data. v1 is a stub that records the
 * request and tells the user we'll email them within 24h. A follow-up
 * cron job will produce the ZIP and deliver a signed URL.
 */
Deno.serve(async (req) => {
  const cors = corsHeaders(req);

  const preflight = handlePreflight(req);
  if (preflight) return preflight;

  try {
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...cors, "Content-Type": "application/json" },
      });
    }

    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      global: { headers: { Authorization: authHeader } },
    });
    const {
      data: { user },
      error: userError,
    } = await supabaseUser.auth.getUser();

    if (userError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...cors, "Content-Type": "application/json" },
      });
    }

    const admin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // Best-effort audit trail. The admin_audit_logs table is optional —
    // if it doesn't exist in this env, swallow the error.
    try {
      await admin.from("admin_audit_logs").insert({
        admin_user_id: user.id,
        action: "export_user_data_requested",
        entity_type: "user",
        entity_id: user.id,
        details: { requested_at: new Date().toISOString() },
      });
    } catch {
      /* ignore */
    }

    return new Response(
      JSON.stringify({
        ok: true,
        url: null,
        message: "We'll email your export within 24h.",
      }),
      { headers: { ...cors, "Content-Type": "application/json" } },
    );
  } catch (err: unknown) {
    console.error("export-user-data error:", err);
    await logSystemError({
      function_name: "export-user-data",
      error_type: "DATA_EXPORT_ERROR",
      severity: "warning",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    return new Response(
      JSON.stringify({
        error: err instanceof Error ? err.message : String(err),
      }),
      {
        status: 500,
        headers: { ...cors, "Content-Type": "application/json" },
      },
    );
  }
});

