// @ts-nocheck
// deno-lint-ignore-file no-explicit-any
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { corsHeaders, handlePreflight } from "../_shared/cors.ts";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

/**
 * Soft-delete the caller's account:
 *   1. Set users.status = 'deleted' (existing CHECK constraint allows it).
 *   2. Revoke the current session.
 *
 * Dodo subscription cancellation and hard-delete of the auth.users row
 * are handled by a follow-up cron (30-day grace period). This endpoint
 * intentionally does NOT call dodo here — the user can re-activate
 * during the grace window.
 */
Deno.serve(async (req) => {
  const cors = corsHeaders(req);

  const preflight = handlePreflight(req);
  if (preflight) return preflight;

  try {
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...cors, "Content-Type": "application/json" },
      });
    }

    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      global: { headers: { Authorization: authHeader } },
    });
    const {
      data: { user },
      error: userError,
    } = await supabaseUser.auth.getUser();

    if (userError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...cors, "Content-Type": "application/json" },
      });
    }

    const admin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // Mark the user row as deleted (status is a CHECK-constrained enum:
    // 'active' | 'suspended' | 'deleted' — see migration 0001_bubs_core).
    const { error: updErr } = await admin
      .from("users")
      .update({ status: "deleted" })
      .eq("id", user.id);
    if (updErr) throw updErr;

    try {
      await admin.from("admin_audit_logs").insert({
        admin_user_id: user.id,
        action: "account_deletion_requested",
        entity_type: "user",
        entity_id: user.id,
        details: { requested_at: new Date().toISOString() },
      });
    } catch {
      /* ignore if audit table not present in this env */
    }

    // Revoke the current access token. The client will also call
    // signOut() after the response lands.
    try {
      await admin.auth.admin.signOut(user.id);
    } catch {
      /* ignore — client signOut is authoritative */
    }

    return new Response(
      JSON.stringify({
        ok: true,
        message: "Account scheduled for deletion.",
      }),
      { headers: { ...cors, "Content-Type": "application/json" } },
    );
  } catch (err: unknown) {
    console.error("delete-user-account error:", err);
    await logSystemError({
      function_name: "delete-user-account",
      error_type: "ACCOUNT_DELETION_ERROR",
      severity: "critical",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    return new Response(
      JSON.stringify({
        error: err instanceof Error ? err.message : String(err),
      }),
      {
        status: 500,
        headers: { ...cors, "Content-Type": "application/json" },
      },
    );
  }
});

