/**
 * Narrow typed wrapper for tables/columns that exist in the database
 * but have not yet been regenerated into `types.ts`.
 *
 * Prefer this over `(supabase as any)` casts (forbidden by CLAUDE.md):
 * every escape here is a named, shaped type with an `unknown` pivot, so
 * no `any` leaks into the rest of the codebase.
 *
 * Regenerate types after running the migration:
 *   supabase gen types typescript --project-id <ref> \
 *     > src/integrations/supabase/types.ts
 * …then delete the entry below and switch call-sites back to the plain
 * `supabase` client.
 */
import type { SupabaseClient } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";

export type NotificationPreferenceRow = {
  user_id: string;
  event_key: string;
  email_enabled: boolean;
  in_app_enabled: boolean;
  updated_at: string;
};

export type NotificationPreferenceInsert = {
  user_id: string;
  event_key: string;
  email_enabled?: boolean;
  in_app_enabled?: boolean;
};

export type ProfileRowWithTimezone = {
  user_id: string;
  full_name: string | null;
  avatar_url: string | null;
  timezone: string | null;
};

type ExtendedDatabase = {
  public: {
    Tables: {
      notification_preferences: {
        Row: NotificationPreferenceRow;
        Insert: NotificationPreferenceInsert;
        Update: Partial<NotificationPreferenceRow>;
        Relationships: [];
      };
    };
    Views: {
      profiles_with_timezone: {
        Row: ProfileRowWithTimezone;
        Insert: Partial<ProfileRowWithTimezone>;
        Update: Partial<ProfileRowWithTimezone>;
        Relationships: [];
      };
    };
    Functions: Record<string, never>;
    Enums: Record<string, never>;
    CompositeTypes: Record<string, never>;
  };
};

/**
 * Same runtime instance as the typed `supabase` client — cast through
 * `unknown` so the un-regenerated tables become callable without `any`.
 */
export const supabaseExt =
  supabase as unknown as SupabaseClient<ExtendedDatabase>;

