   * notification_preferences row has email_enabled = true (default true).
   * If omitted, only the in-app notification fires.
   */
  email?: EmailPayload;
};

type Prefs = { email_enabled: boolean; in_app_enabled: boolean };

const PREFS_TABLE = "notification_preferences" as const;

async function getPrefs(
  userId: string,
  eventKey: NotificationEventKey,
): Promise<Prefs> {
  const { data } = await supabase
    .from(PREFS_TABLE)
    .select("email_enabled, in_app_enabled")
    .eq("user_id", userId)
    .eq("event_key", eventKey)
    .maybeSingle();

  return {
    email_enabled: data?.email_enabled ?? true,
    in_app_enabled: data?.in_app_enabled ?? true,
  };
}

/**
 * Respect the user's notification preferences and fan out to the
 * `notifications` table (in-app) and/or Resend via the `send-email`
 * edge function.
 *
 * Missing preference row ⇒ both channels enabled (default).
 * Errors on individual channels are logged, never thrown — a failed
 * email must not drop the in-app notification.
 */
export async function dispatchNotification({
  userId,
  eventKey,
  title,
  body,
  link,
  email,
}: DispatchNotificationArgs): Promise<{
  inAppDelivered: boolean;
  emailDelivered: boolean;
}> {
  const prefs = await getPrefs(userId, eventKey);

  let inAppDelivered = false;
  let emailDelivered = false;

  if (prefs.in_app_enabled) {
    const { error } = await supabase.from("notifications").insert({
      user_id: userId,
      title,
      body: body ?? null,
      link: link ?? null,
      type: eventKey,
    });
    if (error) {
      console.error("[dispatchNotification] in-app insert failed", error);
    } else {
      inAppDelivered = true;
    }
  }

  if (prefs.email_enabled && email) {
    const { error } = await supabase.functions.invoke("send-email", {
      body: {
        to: email.to,
        template_key: email.templateKey,
        variables: email.variables,
      },
    });
    if (error) {
      console.error("[dispatchNotification] email invoke failed", error);
    } else {
      emailDelivered = true;
    }
  }

  return { inAppDelivered, emailDelivered };
}

