"use client";

import { useState, useEffect } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { Save, Loader2 } from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

const ConfigTab = () => {
  const qc = useQueryClient();
  const [saving, setSaving] = useState(false);

  const { data: config } = useQuery({
    queryKey: ["admin_config"],
    queryFn: async () => {
      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
      if (error) throw error;
      return data;
    },
  });

  const [form, setForm] = useState({
    max_resumes_per_job: 1000,
    max_file_size_mb: 5,
    resume_retention_days: 30,
    email_ingestion_enabled: false,
    auto_rank_enabled: false,
    blind_mode_default: false,
  });
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    if (config && !loaded) {
      setForm({
        max_resumes_per_job: config.max_resumes_per_job ?? 1000,
        max_file_size_mb: config.max_file_size_mb ?? 5,
        resume_retention_days: config.resume_retention_days ?? 30,
        email_ingestion_enabled: config.email_ingestion_enabled ?? false,
        auto_rank_enabled: config.auto_rank_enabled ?? false,
        blind_mode_default: config.blind_mode_default ?? false,
      });
      setLoaded(true);
    }
  }, [config, loaded]);

  const validate = () => {
    if (form.max_resumes_per_job < 1) { toast.error("Max resumes per job must be at least 1"); return false; }
    if (form.max_file_size_mb < 1 || form.max_file_size_mb > 50) { toast.error("Max file size must be 1–50 MB"); return false; }
    if (form.resume_retention_days < 1) { toast.error("Retention days must be at least 1"); return false; }
    return true;
  };

  const save = async () => {
    if (!validate()) return;
    setSaving(true);
    try {
      const { error } = await supabase.from("platform_config").update({
        max_resumes_per_job: form.max_resumes_per_job,
        max_file_size_mb: form.max_file_size_mb,
        resume_retention_days: form.resume_retention_days,
        email_ingestion_enabled: form.email_ingestion_enabled,
        auto_rank_enabled: form.auto_rank_enabled,
        blind_mode_default: form.blind_mode_default,
      }).eq("account_id", config?.account_id);
      if (error) { toast.error(error.message); return; }
      toast.success("Config updated");
      logAuditAction("config.update", "platform_config", config?.account_id ?? undefined, form);
      qc.invalidateQueries({ queryKey: ["admin_config"] });
      qc.invalidateQueries({ queryKey: ["platform_config"] });
    } finally {
      setSaving(false);
    }
  };

  return (
    <Card>
      <CardHeader className="pb-3"><CardTitle className="text-lg">Platform Configuration</CardTitle></CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          <div>
            <Label>Max Resumes/Job</Label>
            <Input type="number" min={1} value={form.max_resumes_per_job} onChange={(e) => setForm({ ...form, max_resumes_per_job: parseInt(e.target.value) || 0 })} />
          </div>
          <div>
            <Label>Max File Size (MB)</Label>
            <Input type="number" min={1} max={50} value={form.max_file_size_mb} onChange={(e) => setForm({ ...form, max_file_size_mb: parseInt(e.target.value) || 0 })} />
          </div>
          <div>
            <Label>Retention Days</Label>
            <Input type="number" min={1} value={form.resume_retention_days} onChange={(e) => setForm({ ...form, resume_retention_days: parseInt(e.target.value) || 0 })} />
          </div>
        </div>

        <div className="border-t border-border pt-4 mt-2 space-y-4">
          <p className="text-sm font-semibold">Feature Toggles</p>
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium">Email Ingestion</p>
              <p className="text-xs text-muted-foreground">Allow users to forward resumes via email</p>
            </div>
            <Switch checked={form.email_ingestion_enabled} onCheckedChange={(v) => setForm({ ...form, email_ingestion_enabled: v })} />
          </div>
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium">Auto-Rank</p>
              <p className="text-xs text-muted-foreground">Automatically rank resumes when uploaded</p>
            </div>
            <Switch checked={form.auto_rank_enabled} onCheckedChange={(v) => setForm({ ...form, auto_rank_enabled: v })} />
          </div>
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium">Blind Mode Default</p>
              <p className="text-xs text-muted-foreground">Hide candidate names by default in rankings</p>
            </div>
            <Switch checked={form.blind_mode_default} onCheckedChange={(v) => setForm({ ...form, blind_mode_default: v })} />
          </div>
        </div>

        <Button onClick={save} disabled={saving}>
          {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
          Save Configuration
        </Button>
      </CardContent>
    </Card>
  );
};

export default ConfigTab;

