          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium">Auto-Rank</p>
              <p className="text-xs text-muted-foreground">Automatically rank resumes when uploaded</p>
            </div>
            <Switch checked={form.auto_rank_enabled} onCheckedChange={(v) => setForm({ ...form, auto_rank_enabled: v })} />
          </div>
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium">Blind Mode Default</p>
              <p className="text-xs text-muted-foreground">Hide candidate names by default in rankings</p>
            </div>
            <Switch checked={form.blind_mode_default} onCheckedChange={(v) => setForm({ ...form, blind_mode_default: v })} />
          </div>
        </div>

        <Button onClick={save} disabled={saving}>
          {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
          Save Configuration
        </Button>
      </CardContent>
    </Card>
  );
};

export default ConfigTab;
